export interface ConnectorConfig {
  /** Notion API integration token (Bearer). Env: NOTION_API_KEY */
  notionApiKey: string
  /** Notion database ID for the 'Signed' database. Env: NOTION_DATABASE_ID */
  notionDatabaseId: string
  /** Optional mapping from Pipedrive owner_id (number) to Notion user ID (string). */
  ownerIdMap?: Record<number, string>
  /** Injected fetch for testing. */
  fetch?: typeof fetch
}

export interface PipedriveWebhookPayload {
  meta: {
    action: string
    entity: string
    entity_id: string
    timestamp: string
    version: string
    webhook_id: string
    webhook_owner_id: string
    change_source: string
    attempt: number
    host: string
  }
  data: {
    id: number
    title: string
    value: number
    currency: string
    owner_id: number
    status: string
    won_time: string | null
    [key: string]: unknown
  }
  previous: {
    status: string
    [key: string]: unknown
  }
}

export interface HandleResult {
  notionPageId: string
  notionPageUrl: string
}

function requireField<T>(obj: unknown, path: string): T {
  const parts = path.split('.')
  let current: unknown = obj
  for (const part of parts) {
    if (current === null || current === undefined || typeof current !== 'object') {
      throw new Error(`Missing required field: ${path}`)
    }
    current = (current as Record<string, unknown>)[part]
  }
  if (current === undefined || current === null) {
    throw new Error(`Missing required field: ${path}`)
  }
  return current as T
}

export async function handle(
  payload: unknown,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch

  // Validate webhook structure
  const metaAction = requireField<string>(payload, 'meta.action')
  if (metaAction !== 'change') {
    throw new Error(`Unsupported meta.action: ${metaAction}. Expected 'change'.`)
  }

  const entity = requireField<string>(payload, 'meta.entity')
  if (entity !== 'deal') {
    throw new Error(`Unsupported meta.entity: ${entity}. Expected 'deal'.`)
  }

  const dataStatus = requireField<string>(payload, 'data.status')
  if (dataStatus !== 'won') {
    throw new Error(`Deal status is not 'won': ${dataStatus}`)
  }

  const previousStatus = requireField<string>(payload, 'previous.status')
  if (previousStatus === 'won') {
    throw new Error('Deal was already won; not a move-to-won transition.')
  }

  // Extract required fields
  const title = requireField<string>(payload, 'data.title')
  const value = requireField<number>(payload, 'data.value')
  const ownerId = requireField<number>(payload, 'data.owner_id')
  const wonTime = requireField<string | null>(payload, 'data.won_time')

  if (!wonTime) {
    throw new Error('Missing won_time on won deal')
  }

  // Resolve owner to Notion user ID
  let notionUserId: string
  if (config.ownerIdMap && config.ownerIdMap[ownerId]) {
    notionUserId = config.ownerIdMap[ownerId]
  } else {
    throw new Error(
      `No Notion user mapping for Pipedrive owner_id ${ownerId}. Provide ownerIdMap in config.`
    )
  }

  // Format close date as YYYY-MM-DD
  const closeDate = wonTime.split('T')[0] // ISO date prefix

  // Build Notion page creation body
  const notionBody = {
    parent: {
      database_id: config.notionDatabaseId,
    },
    properties: {
      'Deal Title': {
        title: [
          {
            text: {
              content: title,
            },
          },
        ],
      },
      'Deal Value': {
        number: value,
      },
      Owner: {
        people: [
          {
            object: 'user',
            id: notionUserId,
          },
        ],
      },
      'Close Date': {
        date: {
          start: closeDate,
        },
      },
    },
  }

  // Call Notion API
  const response = await fetchImpl('https://api.notion.com/v1/pages', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.notionApiKey}`,
      'Content-Type': 'application/json',
      'Notion-Version': '2022-06-28',
    },
    body: JSON.stringify(notionBody),
  })

  if (!response.ok) {
    const text = await response.text().catch(() => '')
    throw new Error(
      `Notion API error: ${response.status} ${response.statusText} at POST https://api.notion.com/v1/pages - ${text}`
    )
  }

  const result = (await response.json()) as { id: string; url: string }
  return {
    notionPageId: result.id,
    notionPageUrl: result.url,
  }
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { handle, ConnectorConfig, PipedriveWebhookPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  contractFetch,
  fakeFetch,
  jsonResponse,
  TARGET_ENDPOINTS,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      notionApiKey: 'test-notion-key',
      notionDatabaseId: 'test-database-id',
      ownerIdMap: { 12415231: 'notion-user-123' },
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as PipedriveWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.notionPageId).toBe('page-id-generated-by-notion')
  })
})

describe('handle', () => {
  let baseConfig: ConnectorConfig
  let mockFetch: typeof fetch
  let calls: ReturnType<typeof fakeFetch>['calls']

  beforeEach(() => {
    const { fetch, calls: c } = fakeFetch((req) => {
      if (req.url === 'https://api.notion.com/v1/pages' && req.method === 'POST') {
        return jsonResponse(TARGET_ENDPOINTS[0].response, 200)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })
    mockFetch = fetch
    calls = c
    baseConfig = {
      notionApiKey: 'test-notion-key',
      notionDatabaseId: 'test-database-id',
      ownerIdMap: { 12415231: 'notion-user-123' },
      fetch: mockFetch,
    }
  })

  it('creates a Notion page with correct property mapping on happy path', async () => {
    const payload: PipedriveWebhookPayload = {
      meta: {
        action: 'change',
        entity: 'deal',
        entity_id: '8',
        timestamp: '2022-11-24T13:18:56.089Z',
        version: '2.0',
        webhook_id: '4710827',
        webhook_owner_id: '12094821',
        change_source: 'app',
        attempt: 1,
        host: 'pd-us.pipedrive.com',
      },
      data: {
        id: 8,
        title: 'Sample Org deal',
        value: 100,
        currency: 'EUR',
        owner_id: 12415231,
        status: 'won',
        won_time: '2022-11-24T13:18:55Z',
      },
      previous: {
        status: 'open',
      },
    }

    const result = await handle(payload, baseConfig)

    expect(result.notionPageId).toBe('page-id-generated-by-notion')
    expect(calls.length).toBe(1)
    const call = calls[0]
    expect(call.method).toBe('POST')
    expect(call.url).toBe('https://api.notion.com/v1/pages')
    expect(call.headers.get('authorization')).toBe('Bearer test-notion-key')
    expect(call.headers.get('notion-version')).toBe('2022-06-28')

    const body = call.json as Record<string, unknown>
    expect(body.parent).toEqual({ database_id: 'test-database-id' })
    const props = body.properties as Record<string, unknown>
    expect(props['Deal Title']).toEqual({
      title: [{ text: { content: 'Sample Org deal' } }],
    })
    expect(props['Deal Value']).toEqual({ number: 100 })
    expect(props.Owner).toEqual({
      people: [{ object: 'user', id: 'notion-user-123' }],
    })
    expect(props['Close Date']).toEqual({ date: { start: '2022-11-24' } })
  })

  it('throws when meta.action is not change', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      meta: { ...SOURCE_EXAMPLE.meta, action: 'create' },
    }
    await expect(handle(payload as unknown as PipedriveWebhookPayload, baseConfig)).rejects.toThrow(
      "Unsupported meta.action: create. Expected 'change'."
    )
  })

  it('throws when data.status is not won', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      data: { ...SOURCE_EXAMPLE.data, status: 'open' },
    }
    await expect(handle(payload as unknown as PipedriveWebhookPayload, baseConfig)).rejects.toThrow(
      "Deal status is not 'won': open"
    )
  })

  it('throws when previous.status is already won', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      previous: { ...SOURCE_EXAMPLE.previous, status: 'won' },
    }
    await expect(handle(payload as unknown as PipedriveWebhookPayload, baseConfig)).rejects.toThrow(
      'Deal was already won; not a move-to-won transition.'
    )
  })

  it('throws when required field title is missing', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      data: { ...SOURCE_EXAMPLE.data, title: undefined },
    }
    await expect(handle(payload as unknown as PipedriveWebhookPayload, baseConfig)).rejects.toThrow(
      'Missing required field: data.title'
    )
  })

  it('throws when required field value is missing', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      data: { ...SOURCE_EXAMPLE.data, value: undefined },
    }
    await expect(handle(payload as unknown as PipedriveWebhookPayload, baseConfig)).rejects.toThrow(
      'Missing required field: data.value'
    )
  })

  it('throws when required field owner_id is missing', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      data: { ...SOURCE_EXAMPLE.data, owner_id: undefined },
    }
    await expect(handle(payload as unknown as PipedriveWebhookPayload, baseConfig)).rejects.toThrow(
      'Missing required field: data.owner_id'
    )
  })

  it('throws when required field won_time is missing', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      data: { ...SOURCE_EXAMPLE.data, won_time: null },
    }
    await expect(handle(payload as unknown as PipedriveWebhookPayload, baseConfig)).rejects.toThrow(
      'Missing won_time on won deal'
    )
  })

  it('throws when ownerIdMap does not contain the owner_id', async () => {
    const config = { ...baseConfig, ownerIdMap: {} }
    const payload = SOURCE_EXAMPLE as unknown as PipedriveWebhookPayload
    await expect(handle(payload, config)).rejects.toThrow(
      'No Notion user mapping for Pipedrive owner_id 12415231. Provide ownerIdMap in config.'
    )
  })

  it('throws on non-2xx response from Notion API', async () => {
    const { fetch, calls: errorCalls } = fakeFetch(() => jsonResponse({ error: 'unauthorized' }, 401))
    const config = { ...baseConfig, fetch }
    const payload = SOURCE_EXAMPLE as unknown as PipedriveWebhookPayload

    await expect(handle(payload, config)).rejects.toThrow(
      'Notion API error: 401 Unauthorized at POST https://api.notion.com/v1/pages'
    )
    expect(errorCalls.length).toBe(1)
  })

  it('uses injected fetch from config', async () => {
    const { fetch, calls: injectedCalls } = fakeFetch(() =>
      jsonResponse(TARGET_ENDPOINTS[0].response, 200)
    )
    const config = { ...baseConfig, fetch }
    const payload = SOURCE_EXAMPLE as unknown as PipedriveWebhookPayload

    await handle(payload, config)
    expect(injectedCalls.length).toBe(1)
  })
})

